<script setup lang="ts">
import {computed} from 'vue'
import {useRouter} from 'vue-router'
import type {Call,Taxonomy} from '../../shared/interfaces'
import {datetime,duration,resultLabels,kindLabels,stageLabels} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import RecordingBadge from './RecordingBadge.vue'
const props=withDefaults(defineProps<{calls:Call[];taxonomy?:Taxonomy;timezone?:string;selected?:string[];selectable?:boolean}>(),{timezone:'Europe/Moscow',selected:()=>[]})
const emit=defineEmits<{(e:'update:selected',value:string[]):void}>(),router=useRouter()
const all=computed(()=>props.calls.length>0&&props.calls.every(c=>props.selected.includes(c.id)))
function toggle(id:string){emit('update:selected',props.selected.includes(id)?props.selected.filter(x=>x!==id):[...props.selected,id])}
function toggleAll(){emit('update:selected',all.value?props.selected.filter(id=>!props.calls.some(c=>c.id===id)):[...new Set([...props.selected,...props.calls.map(c=>c.id)])])}
function tags(call:Call){return call.tag_ids.map(id=>props.taxonomy?.tags.find(t=>t.id===id)).filter(t=>!!t).slice(0,2)}
</script>
<template><div class="table-wrap"><table class="data-table"><thead><tr><th v-if="selectable"><input class="call-selection" type="checkbox" aria-label="Выбрать страницу" :checked="all" @change="toggleAll"/></th><th>Клиент / номер</th><th class="recording-column">Запись</th><th>Сотрудник</th><th>Дата и время</th><th>Длительность</th><th>Результат</th><th>Оценка</th><th>Теги / обращение</th><th></th></tr></thead><tbody><tr v-for="call in calls" :key="call.id" class="clickable" tabindex="0" @click="router.push('/calls/'+call.id)" @keydown.enter="router.push('/calls/'+call.id)"><td v-if="selectable" @click.stop><input class="call-selection" type="checkbox" :aria-label="`Выбрать звонок ${call.phone}`" :checked="selected.includes(call.id)" @change="toggle(call.id)"/></td><td><div class="cell-person"><span class="phone-direction" :class="{missed:['not answered','rejected'].includes(call.provider_result),out:call.direction==='out'}"><Icon name="phone" :size="13"/></span><div><span class="primary-text">{{call.contact_name||call.phone||'Скрытый номер'}}</span><small>{{call.contact_name?call.phone:call.direction==='out'?'Исходящий':call.direction==='internal'?'Внутренний':'Входящий'}}</small><RecordingBadge class="recording-mobile" :call="call"/></div></div></td><td class="recording-column"><RecordingBadge :call="call"/></td><td><span class="primary-text">{{call.employee||'Не назначен'}}</span><small>{{kindLabels[call.contact_kind]||'Не определено'}}</small></td><td>{{datetime(call.started_at,timezone)}}<small>{{stageLabels[call.stage]||call.stage}}</small></td><td>{{duration(call.duration)}}</td><td><span class="badge" :class="call.human_connected?'teal':['not answered','rejected','failed'].includes(call.provider_result)?'red':'amber'">{{resultLabels[call.provider_result]||'Неизвестно'}}</span></td><td><span class="score" :class="call.score===null?'unknown':call.score<50?'low':call.score<75?'medium':''">{{call.score===null?'—':Math.round(call.score)}}</span></td><td><div class="inline-labels"><span v-for="tag in tags(call)" :key="tag!.id" class="badge outline" :style="{color:tag!.color}">{{tag!.name}}</span><span v-if="!tags(call).length" class="subtle">—</span></div></td><td><Icon name="chevron" :size="14" style="color:#aebfbd"/></td></tr></tbody></table></div></template>
